#!/usr/bin/env bashecho "[backup-drill] tarball sha256=$OUTPUT_SHA"# soland production backup drill.echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# Captures three artifacts into a single tarball with a manifest thatecho "[backup-drill] tarball sha256=$OUTPUT_SHA"# pins per-artifact checksums:echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#   1. `pg_dump` of the soland database (custom `Fc` format).echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#   2. Snapshot of the keystore-persisted anchorer signing seed (whenecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#      `SOLAND_USE_KEYSTORE=true`). Implemented via `soland-rotate-drillecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#      --export-only` so we can use the same KeyStore trait the runningecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#      server uses (no out-of-band keychain probing).echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#   3. The `multisig_pending` table's full state (rows + claim_seq +echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#      partials), exported as JSONL, so the restore drill can walkecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#      every row and assert its aggregability post-restore.echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# Honours the existing PASION_* / SOLAND_* env conventions:echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#   - `DATABASE_URL` (or `PASION_DATABASE_URL` as override)echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#   - `SOLAND_SERVICE_DID` — used to scope the keystore lookupecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#   - `SOLAND_USE_KEYSTORE` — when "true", export the platform keystore seedecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#   - `SOLAND_BACKUP_DIR`  — where the output tarball is writtenecho "[backup-drill] tarball sha256=$OUTPUT_SHA"#                             (defaults to ./backups/soland-<ts>.tar.gz)echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# Exit codes:echo "[backup-drill] tarball sha256=$OUTPUT_SHA"#   0 success;  1 invariant/IO failure;  2 prerequisite missing.echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"set -euo pipefailecho "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"DRILL_TS="$(date -u +%Y%m%dT%H%M%SZ)"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"WORKDIR="$(mktemp -d -t soland-backup-XXXXXX)"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"trap 'rm -rf "$WORKDIR"' EXITecho "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"DATABASE_URL="${PASION_DATABASE_URL:-${DATABASE_URL:-}}"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"SERVICE_DID="${SOLAND_SERVICE_DID:-did:web:soland.local}"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"USE_KEYSTORE="${SOLAND_USE_KEYSTORE:-false}"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"BACKUP_DIR="${SOLAND_BACKUP_DIR:-./backups}"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"mkdir -p "$BACKUP_DIR"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"OUTPUT="${BACKUP_DIR}/soland-${DRILL_TS}.tar.gz"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"if [ -z "$DATABASE_URL" ]; thenecho "[backup-drill] tarball sha256=$OUTPUT_SHA"    echo "[backup-drill] FATAL: DATABASE_URL (or PASION_DATABASE_URL) is unset" >&2echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    exit 2echo "[backup-drill] tarball sha256=$OUTPUT_SHA"fiecho "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"for cmd in pg_dump psql sha256sum tar jq; doecho "[backup-drill] tarball sha256=$OUTPUT_SHA"    if ! command -v "$cmd" >/dev/null 2>&1; thenecho "[backup-drill] tarball sha256=$OUTPUT_SHA"        echo "[backup-drill] FATAL: missing prerequisite '$cmd'" >&2echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        exit 2echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    fiecho "[backup-drill] tarball sha256=$OUTPUT_SHA"doneecho "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] timestamp=$DRILL_TS service_did=$SERVICE_DID workdir=$WORKDIR"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# ── 1. pg_dump ───────────────────────────────────────────────────────────echo "[backup-drill] tarball sha256=$OUTPUT_SHA"DUMP_PATH="${WORKDIR}/soland-database.dump"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] step 1/3: pg_dump custom-format"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"pg_dump --format=custom --no-owner --no-acl --file="$DUMP_PATH" "$DATABASE_URL"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"DUMP_SHA="$(sha256sum "$DUMP_PATH" | awk '{print $1}')"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill]   sha256=$DUMP_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# ── 2. keystore snapshot ─────────────────────────────────────────────────echo "[backup-drill] tarball sha256=$OUTPUT_SHA"KEYSTORE_PATH="${WORKDIR}/keystore.json"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"if [ "$USE_KEYSTORE" = "true" ]; thenecho "[backup-drill] tarball sha256=$OUTPUT_SHA"    echo "[backup-drill] step 2/3: keystore export via soland-rotate-drill --export-only"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    cargo run --quiet --bin soland-rotate-drill -- \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        --export-only \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        --service-did "$SERVICE_DID" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        --output "$KEYSTORE_PATH"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"elseecho "[backup-drill] tarball sha256=$OUTPUT_SHA"    echo "[backup-drill] step 2/3: keystore export skipped (SOLAND_USE_KEYSTORE != true)"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    cat >"$KEYSTORE_PATH" <<EOFecho "[backup-drill] tarball sha256=$OUTPUT_SHA"{ "skipped": true, "reason": "SOLAND_USE_KEYSTORE is not 'true'" }echo "[backup-drill] tarball sha256=$OUTPUT_SHA"EOFecho "[backup-drill] tarball sha256=$OUTPUT_SHA"fiecho "[backup-drill] tarball sha256=$OUTPUT_SHA"KEYSTORE_SHA="$(sha256sum "$KEYSTORE_PATH" | awk '{print $1}')"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill]   sha256=$KEYSTORE_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# ── 3. multisig_pending state ────────────────────────────────────────────echo "[backup-drill] tarball sha256=$OUTPUT_SHA"MULTISIG_PATH="${WORKDIR}/multisig_pending.jsonl"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] step 3/3: multisig_pending JSONL export"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"psql --quiet --tuples-only --no-align "$DATABASE_URL" >"$MULTISIG_PATH" <<'SQL'echo "[backup-drill] tarball sha256=$OUTPUT_SHA"SELECT json_build_object(echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'anchor_id',          anchor_id,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'space_id',           space_id,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'threshold_k',        threshold_k,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'threshold_n',        threshold_n,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'members',            members,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'canonical_b64',      canonical_b64,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'partials',           partials,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'created_at',         to_char(created_at AT TIME ZONE 'UTC',echo "[backup-drill] tarball sha256=$OUTPUT_SHA"                                   'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'expires_at',         to_char(expires_at AT TIME ZONE 'UTC',echo "[backup-drill] tarball sha256=$OUTPUT_SHA"                                   'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'claimed_by_node_id', claimed_by_node_id,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'claimed_until',      CASEecho "[backup-drill] tarball sha256=$OUTPUT_SHA"                              WHEN claimed_until IS NULL THEN NULLecho "[backup-drill] tarball sha256=$OUTPUT_SHA"                              ELSE to_char(claimed_until AT TIME ZONE 'UTC',echo "[backup-drill] tarball sha256=$OUTPUT_SHA"                                            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')echo "[backup-drill] tarball sha256=$OUTPUT_SHA"                          END,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    'claim_seq',          claim_seqecho "[backup-drill] tarball sha256=$OUTPUT_SHA")::textecho "[backup-drill] tarball sha256=$OUTPUT_SHA"FROM multisig_pendingecho "[backup-drill] tarball sha256=$OUTPUT_SHA"ORDER BY anchor_id;echo "[backup-drill] tarball sha256=$OUTPUT_SHA"SQLecho "[backup-drill] tarball sha256=$OUTPUT_SHA"MULTISIG_ROW_COUNT="$(wc -l <"$MULTISIG_PATH" | awk '{print $1}')"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"MULTISIG_SHA="$(sha256sum "$MULTISIG_PATH" | awk '{print $1}')"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill]   rows=$MULTISIG_ROW_COUNT sha256=$MULTISIG_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# ── manifest ─────────────────────────────────────────────────────────────echo "[backup-drill] tarball sha256=$OUTPUT_SHA"MANIFEST_PATH="${WORKDIR}/manifest.json"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"jq -n \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --arg ts "$DRILL_TS" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --arg did "$SERVICE_DID" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --arg use_ks "$USE_KEYSTORE" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --arg dump_sha "$DUMP_SHA" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --arg ks_sha "$KEYSTORE_SHA" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --arg mp_sha "$MULTISIG_SHA" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    --argjson mp_rows "$MULTISIG_ROW_COUNT" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    '{echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        manifest_version: "1",echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        produced_by: "soland/scripts/backup-drill.sh",echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        timestamp: $ts,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        service_did: $did,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        use_keystore: $use_ks,echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        artifacts: {echo "[backup-drill] tarball sha256=$OUTPUT_SHA"            "soland-database.dump":  { sha256: $dump_sha, kind: "pg_dump_custom" },echo "[backup-drill] tarball sha256=$OUTPUT_SHA"            "keystore.json":         { sha256: $ks_sha, kind: "keystore_seed" },echo "[backup-drill] tarball sha256=$OUTPUT_SHA"            "multisig_pending.jsonl":{ sha256: $mp_sha, kind: "multisig_pending_jsonl",echo "[backup-drill] tarball sha256=$OUTPUT_SHA"                                       row_count: $mp_rows }echo "[backup-drill] tarball sha256=$OUTPUT_SHA"        }echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    }' >"$MANIFEST_PATH"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"MANIFEST_SHA="$(sha256sum "$MANIFEST_PATH" | awk '{print $1}')"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] manifest sha256=$MANIFEST_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"# ── tarball ──────────────────────────────────────────────────────────────echo "[backup-drill] tarball sha256=$OUTPUT_SHA"tar -czf "$OUTPUT" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    -C "$WORKDIR" \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    manifest.json \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    soland-database.dump \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    keystore.json \echo "[backup-drill] tarball sha256=$OUTPUT_SHA"    multisig_pending.jsonlecho "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"OUTPUT_SHA="$(sha256sum "$OUTPUT" | awk '{print $1}')"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] OK -> $OUTPUT"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"echo "[backup-drill] tarball sha256=$OUTPUT_SHA"